import { readFileSync, writeFileSync } from 'node:fs';
import { inflateSync } from 'node:zlib';

const buf = readFileSync('/workspace/dataset/test2_executable');
const MAGIC = Buffer.from([0x4d, 0x45, 0x49, 0x0c, 0x0b, 0x0a, 0x0b, 0x0e]);
let cp = -1;
for (let i = buf.length - 8; i >= 0; i--) {
  let ok = true;
  for (let j = 0; j < 8; j++) if (buf[i + j] !== MAGIC[j]) { ok = false; break; }
  if (ok) { cp = i; break; }
}
const pkgLen = buf.readUInt32BE(cp + 8);
const tocOff = buf.readUInt32BE(cp + 12);
const tocLen = buf.readUInt32BE(cp + 16);
const archStart = cp + 88 - pkgLen;
let p = archStart + tocOff;
const tocEnd = p + tocLen;
let pyzEntry = null;
while (p < tocEnd) {
  const el = buf.readUInt32BE(p);
  const off = buf.readUInt32BE(p + 4), cl = buf.readUInt32BE(p + 8);
  const cf = buf[p + 16], ty = String.fromCharCode(buf[p + 17]);
  const nm = buf.subarray(p + 18, p + el).toString('latin1').replace(/\0+$/, '');
  if (ty === 'z') pyzEntry = { off, cl, cf };
  p += el;
}
let pyz = buf.subarray(archStart + pyzEntry.off, archStart + pyzEntry.off + pyzEntry.cl);
if (pyzEntry.cf) pyz = inflateSync(pyz);
const pyzTocOff = pyz.readUInt32BE(8);

// minimal marshal reader: supports dict/list/tuple/str/int needed for TOC
function parser(b) {
  let pos = 0;
  const refs = [];
  const rd = n => { const r = b.subarray(pos, pos + n); pos += n; return r; };
  function parse() {
    let t = rd(1)[0];
    t &= 0x7f;
    const c = String.fromCharCode(t);
    switch (c) {
      case '0': case 'N': return null;
      case 'F': return false;
      case 'T': return true;
      case 'i': return rd(4).readInt32LE(0);
      case 's': { const n = rd(4).readInt32LE(0); return rd(n).toString('latin1'); }
      case 'u': { const n = rd(4).readInt32LE(0); return rd(n).toString('utf8'); }
      case 'z': case 'Z': case 'a': case 'A': { const n = rd(1)[0]; return rd(n).toString('utf8'); }
      case ')': { const n = rd(1)[0]; const v = []; for (let i = 0; i < n; i++) v.push(parse()); return v; }
      case '(': { const n = rd(4).readInt32LE(0); const v = []; for (let i = 0; i < n; i++) v.push(parse()); return v; }
      case '[': { const n = rd(4).readInt32LE(0); const v = []; for (let i = 0; i < n; i++) v.push(parse()); return v; }
      case '{': { const v = {}; for (;;) { const k = parse(); if (k === null) break; v[k] = parse(); } return v; }
      case 'r': return refs[rd(4).readInt32LE(0)];
      default: throw new Error('type ' + JSON.stringify(c) + ' @' + pos);
    }
  }
  return { parse };
}

const pyzToc = parser(pyz.subarray(pyzTocOff)).parse();
const keys = Object.keys(pyzToc);
console.log('toc type ok, entries:', keys.length);
console.log(keys.filter(k => /sqlparse/.test(k)).join('\n'));

for (const k of keys) {
  if (/sqlparse[.](lexer|engine[.]statement_splitter|engine[.]filter_stack|__init__)$/.test(k)) {
    const [typ, off, len] = pyzToc[k];
    const data = inflateSync(pyz.subarray(off, off + len));
    writeFileSync('/tmp/' + k.replace(/\./g, '_') + '.pycdata', data);
    console.log('\n===== ', k, ' inflated:', data.length, 'bytes =====');
