import { readFileSync } from 'node:fs';

// Full-ish marshal parser for Python 3.12
function parser(b) {
  let pos = 0;
  const refs = [];
  const rd = n => { const r = b.subarray(pos, pos + n); pos += n; return r; };
  function parse() {
    let t = rd(1)[0];
    const flagRef = (t & 0x80) !== 0;
    t &= 0x7f;
    const c = String.fromCharCode(t);
    let val, n, i;
    switch (c) {
      case '0': return undefined;         // NULL (only as terminator)
      case 'N': return null;
      case 'F': return false;
      case 'T': return true;
      case '.': return '...';
      case 'i': return rd(4).readInt32LE(0);
      case 'I': { n = rd(4).readInt32LE(0); let v = 0n; const d = rd(Math.abs(n) * 2); for (let k = Math.abs(n) - 1; k >= 0; k--) v = (v << 15n) | BigInt(d.readUInt16LE(k * 2)); return n < 0 ? -v : v; }
      case 'g': return rd(8).readDoubleLE(0);
      case 'y': case 'x': { n = rd(8); const re = n.readDoubleLE(0), im = n.readDoubleLE(8); pos += 8; return `${re}${im < 0 ? '' : '+'}${im}j`; }
      case 's': n = rd(4).readInt32LE(0); val = { __bytes: rd(n).toString('latin1') }; break;
      case 'u': n = rd(4).readInt32LE(0); val = rd(n).toString('utf8'); break;
      case 'z': case 'Z': case 'a': case 'A': n = rd(1)[0]; val = rd(n).toString('utf8'); break;
      case ')': n = rd(1)[0]; val = []; if (flagRef) refs.push(val); for (i = 0; i < n; i++) val.push(parse()); return val;
      case '(': n = rd(4).readInt32LE(0); val = []; if (flagRef) refs.push(val); for (i = 0; i < n; i++) val.push(parse()); return val;
      case '[': n = rd(4).readInt32LE(0); val = []; if (flagRef) refs.push(val); for (i = 0; i < n; i++) val.push(parse()); return val;
      case '<': case '>': n = rd(4).readInt32LE(0); val = { __set: [] }; if (flagRef) refs.push(val); for (i = 0; i < n; i++) val.__set.push(parse()); return val;
      case '{': val = {}; if (flagRef) refs.push(val); for (;;) { const k = parse(); if (k === undefined) break; val[String(k)] = parse(); } return val;
      case 'r': return refs[rd(4).readInt32LE(0)];
      case 'c': {
        val = { __code: true };
        if (flagRef) refs.push(val);
        val.argcount = rd(4).readInt32LE(0);
        val.posonly = rd(4).readInt32LE(0);
        val.kwonly = rd(4).readInt32LE(0);
        val.stacksize = rd(4).readInt32LE(0);
        val.flags = rd(4).readInt32LE(0);
        val.code = parse();
        val.consts = parse();
        val.names = parse();
        val.localsplusnames = parse();
        val.localspluskinds = parse();
        val.filename = parse();
        val.name = parse();
        val.qualname = parse();
        val.firstlineno = rd(4).readInt32LE(0);
        val.linetable = parse();
        val.exceptiontable = parse();
        return val;
      }
      default: throw new Error('marshal type ' + JSON.stringify(c) + ' @' + pos);
    }
    if (flagRef) refs.push(val);
    return val;
  }
  return { parse, pos: () => pos };
}

function show(v) {
  if (v && v.__bytes !== undefined) return 'b' + JSON.stringify(v.__bytes.length > 120 ? v.__bytes.slice(0, 120) + '…' : v.__bytes);
  if (v && v.__set) return 'set' + JSON.stringify(v.__set.map(show));
  if (Array.isArray(v)) return '(' + v.map(show).join(', ') + ')';
  if (v && v.__code) return `<code ${v.name}>`;
  if (typeof v === 'string') return JSON.stringify(v.length > 200 ? v.slice(0, 200) + '…' : v);
  return String(v);
}

function dump(co, depth) {
  const pad = '  '.repeat(depth);
  console.log(`${pad}### code ${co.qualname || co.name} (line ${co.firstlineno})`);
  console.log(`${pad}  names: ${show(co.names)}`);
  console.log(`${pad}  locals: ${show(co.localsplusnames)}`);
  for (const cst of co.consts || []) {
    if (cst && cst.__code) continue;
    console.log(`${pad}  const: ${show(cst)}`);
  }
  if (co.code && co.code.__bytes) {
    writeCode(co);
  }
  for (const cst of co.consts || []) {
    if (cst && cst.__code) dump(cst, depth + 1);
  }
}

// 3.12 opcode table (subset, enough for reading logic)
const OPS = [];
const op = (n, name, hasArg = true) => { OPS[n] = { name, hasArg }; };
