op(152, 'DELETE_GLOBAL'); op(153, 'LOAD_CONST'); op(154, 'LOAD_NAME'); op(157, 'BUILD_STRING');
op(159, 'JUMP_IF_NOT_EXC_MATCH'); op(160, 'CHECK_EXC_MATCH'); op(162, 'BEFORE_ASYNC_WITH');
op(163, 'BEFORE_WITH'); op(164, 'END_ASYNC_FOR'); op(165, 'STORE_SUBSCR'); op(171, 'CALL');
op(172, 'KW_NAMES'); op(173, 'POP_JUMP_IF_FALSE'); op(174, 'POP_JUMP_IF_TRUE'); op(175, 'CONTINUE_LOOP');
op(181, 'WITH_EXCEPT_START'); op(187, 'LOAD_SMALL_INT'); op(189, 'HAS_ARG');
// generic fallbacks for common ones
const CMP = ['<', '<=', '==', '!=', '>', '>='];

function disasm(co) {
  const bytes = Buffer.from(co.code.__bytes, 'latin1');
  const lines = [];
  let ext = 0;
  for (let i = 0; i < bytes.length; i += 2) {
    const opc = bytes[i];
