    else if (name === 'BINARY_OP') { const B = ['+', '-', '*', '/', '//', '%', '@', '**', '<<', '>>', '&', '|', '^', '+=', '-=', '*=', '/=', '//=', '%=', '@=', '**=', '<<=', '>>=', '&=', '|=', '^=']; detail = B[arg] || arg; }
