import { readFileSync, writeFileSync } from 'node:fs';
import { inflateSync } from 'node:zlib';

const buf = readFileSync('/workspace/dataset/test2_executable');
const MAGIC = Buffer.from([0x4d, 0x45, 0x49, 0x0c, 0x0b, 0x0a, 0x0b, 0x0e]);
let cp = -1;
for (let i = buf.length - 8; i >= 0; i--) {
  let ok = true;
  for (let j = 0; j < 8; j++) if (buf[i + j] !== MAGIC[j]) { ok = false; break; }
  if (ok) { cp = i; break; }
}
const pkgLen = buf.readUInt32BE(cp + 8), tocOff = buf.readUInt32BE(cp + 12), tocLen = buf.readUInt32BE(cp + 16);
const archStart = cp + 88 - pkgLen;
let p = archStart + tocOff;
const tocEnd = p + tocLen;
while (p < tocEnd) {
  const el = buf.readUInt32BE(p);
  const off = buf.readUInt32BE(p + 4), cl = buf.readUInt32BE(p + 8), ul = buf.readUInt32BE(p + 12);
  const cf = buf[p + 16], ty = String.fromCharCode(buf[p + 17]);
  const nm = buf.subarray(p + 18, p + el).toString('latin1').replace(/\0+$/, '');
  if (nm.includes('libpython')) {
    let data = buf.subarray(archStart + off, archStart + off + cl);
    if (cf) data = inflateSync(data);
    writeFileSync('/tmp/libpython.so', data);
    console.log('wrote libpython', data.length);
  }
  p += el;
}

