const {readFileSync}=require('node:fs');
const {inflateSync}=require('node:zlib');
const buf=readFileSync('/workspace/dataset/test2_executable');
const MAGIC=Buffer.from([0x4d,0x45,0x49,0x0c,0x0b,0x0a,0x0b,0x0e]);
let cp=-1;
for(let i=buf.length-8;i>=0;i--){let ok=true;for(let j=0;j<8;j++)if(buf[i+j]!==MAGIC[j]){ok=false;break;}if(ok){cp=i;break;}}
const pkgLen=buf.readUInt32BE(cp+8),tocOff=buf.readUInt32BE(cp+12),tocLen=buf.readUInt32BE(cp+16);
const archStart=cp+88-pkgLen;
let p=archStart+tocOff;
while(p<archStart+tocOff+tocLen){
  const el=buf.readUInt32BE(p);const off=buf.readUInt32BE(p+4),cl=buf.readUInt32BE(p+8);
  const cf=buf[p+16];const nm=buf.subarray(p+18,p+el).toString('latin1').replace(/\0+$/,'');
  if(nm==='base_library.zip'){
    let d=buf.subarray(archStart+off,archStart+off+cl);
    if(cf)d=inflateSync(d);
    require('node:fs').writeFileSync('/tmp/base_library.zip',d);
    // list zip central directory names quickly via local headers
    let i=0;const names=[];
    while(i<d.length-4){
      if(d.readUInt32LE(i)===0x04034b50){
        const nl=d.readUInt16LE(i+26),el2=d.readUInt16LE(i+28);
        names.push(d.subarray(i+30,i+30+nl).toString('latin1'));
        const cs=d.readUInt32LE(i+18);
        i=i+30+nl+el2+cs;
      } else i++;
    }
    console.log(names.join('\n'));
    break;
  }
  p+=el;
}
" 2>&1 | head -40

