import { readFileSync } from 'node:fs';
// reuse marshal parser from disasm_pyc.mjs by inlining
const src = readFileSync('/tmp/disasm_pyc.mjs', 'utf8');
const parserPart = src.slice(src.indexOf('function parser'), src.indexOf('function show'));
eval(parserPart);

const data = readFileSync(process.argv[2]);
const code = parser(data).parse();

function walk(co, depth) {
  if (!co || !co.__code) return;
  const pad = '  '.repeat(depth);
  console.log(`${pad}=== ${co.qualname || co.name} (line ${co.firstlineno}) ===`);
  // find code bytes among fields
  for (const k of Object.keys(co)) {
    const v = co[k];
    if (v && v.__bytes !== undefined && v.__bytes.length > 4) {
      const hex = Buffer.from(v.__bytes, 'latin1').toString('hex');
      console.log(`${pad}  field ${k} [${v.__bytes.length}b]: ${hex}`);
    }
  }
  console.log(`${pad}  consts: ${(co.consts || []).map(c => c && c.__code ? `<code ${c.name}>` : (c && c.__bytes !== undefined ? 'b..' : JSON.stringify(c))).join(' | ')}`);
  console.log(`${pad}  names: ${JSON.stringify(co.names)}`);
  for (const c of co.consts || []) if (c && c.__code) walk(c, depth + 1);
}
walk(code, 0);

