args.command:
cd /tmp && node --input-type=module -e "
import { readFileSync } from 'node:fs';
// inline a debug parser
const b = readFileSync('/tmp/sqlparse_engine_statement_splitter.pycdata');
let pos=0; const refs=[];
const rd=n=>{const r=b.subarray(pos,pos+n);pos+=n;return r;};
let depth=0;
function kind(v){ if(v&&v.__code)return 'code:'+v.name; if(v&&v.__bytes!==undefined)return 'bytes('+v.__bytes.length+')'; if(Array.isArray(v))return 'tuple('+v.length+')'; return typeof v+':'+String(v).slice(0,30); }
function parse(){
  let t=rd(1)[0]; const fl=(t&0x80)!==0; t&=0x7f;
  const c=String.fromCharCode(t); let val,n;
  switch(c){
    case '0': case 'N': return null;
    case 'F': return false; case 'T': return true;
    case 'i': return rd(4).readInt32LE(0);
    case 's': n=rd(4).readInt32LE(0); val={__bytes:rd(n).toString('latin1')}; break;
    case 'u': case 'a': case 'A': n=rd(4).readInt32LE(0); val=rd(n).toString('utf8'); break;
    case 'z': case 'Z': n=rd(1)[0]; val=rd(n).toString('utf8'); break;
    case ')': n=rd(1)[0]; val=[]; if(fl){refs.push(val);/*console.log('ref',refs.length-1,'tuple-reserve')*/} for(let i=0;i<n;i++)val.push(parse()); return val;
    case '(': n=rd(4).readInt32LE(0); val=[]; if(fl)refs.push(val); for(let i=0;i<n;i++)val.push(parse()); return val;
    case '[': n=rd(4).readInt32LE(0); val=[]; if(fl)refs.push(val); for(let i=0;i<n;i++)val.push(parse()); return val;
    case 'r': { const idx=rd(4).readInt32LE(0); console.log('REF', idx, '->', kind(refs[idx])); return refs[idx]; }
    case 'c': { val={__code:true};
      val.argcount=rd(4).readInt32LE(0); val.posonly=rd(4).readInt32LE(0); val.kwonly=rd(4).readInt32LE(0);
      val.stacksize=rd(4).readInt32LE(0); val.flags=rd(4).readInt32LE(0);
      val.code=parse(); val.consts=parse(); val.names=parse(); val.localsplusnames=parse();
      val.localspluskinds=parse(); val.filename=parse(); val.name=parse(); val.qualname=parse();
      val.firstlineno=rd(4).readInt32LE(0); val.linetable=parse(); val.exceptiontable=parse();
      if(fl)refs.push(val); return val; }
    default: throw new Error('type '+JSON.stringify(c)+' @'+pos);
  }
  if(fl){refs.push(val);}
  return val;
}
const co=parse();
console.log('module names:', JSON.stringify(co.names));
" 2>&1 | head -40

