import { readFileSync } from 'node:fs';

function makeParser(b, opts) {
  let pos = 0;
  const refs = [];
  const rd = n => { const r = b.subarray(pos, pos + n); pos += n; return r; };
  function refPush(v, flag) { if (opts.reserveAlways || flag) refs.push(flag ? v : undefined); }
  function refPushLate(v, flag) { if (flag) refs.push(v); }
  function parse() {
    let t = rd(1)[0];
    const flagRef = (t & 0x80) !== 0;
    t &= 0x7f;
    const c = String.fromCharCode(t);
    let val, n;
    switch (c) {
      case '0': case 'N': return null;
      case 'F': return false;
      case 'T': return true;
      case 'i': return rd(4).readInt32LE(0);
      case 's': n = rd(4).readInt32LE(0); val = { __bytes: rd(n).toString('latin1') }; refPushLate(val, flagRef); return val;
      case 'u': case 'a': case 'A': n = rd(4).readInt32LE(0); val = rd(n).toString('utf8'); refPushLate(val, flagRef); return val;
      case 'z': case 'Z': n = rd(1)[0]; val = rd(n).toString('utf8'); refPushLate(val, flagRef); return val;
      case ')': n = rd(1)[0]; val = [];
        if (opts.containerBefore) refPush(val, flagRef);
        for (let i = 0; i < n; i++) val.push(parse());
        if (!opts.containerBefore) refPush(val, flagRef);
        return val;
      case '(': n = rd(4).readInt32LE(0); val = [];
        if (opts.containerBefore) refPush(val, flagRef);
        for (let i = 0; i < n; i++) val.push(parse());
        if (!opts.containerBefore) refPush(val, flagRef);
        return val;
      case '[': n = rd(4).readInt32LE(0); val = [];
        if (opts.containerBefore) refPush(val, flagRef);
        for (let i = 0; i < n; i++) val.push(parse());
        if (!opts.containerBefore) refPush(val, flagRef);
        return val;
      case '{': val = {};
        if (opts.containerBefore) refPush(val, flagRef);
        for (;;) { const k = parse(); if (k === undefined) break; val[String(k)] = parse(); }
        if (!opts.containerBefore) refPush(val, flagRef);
        return val;
      case 'r': return refs[rd(4).readInt32LE(0)];
      case 'c': {
        val = { __code: true };
        if (opts.codeBefore) { if (opts.codeAlways || flagRef) refs.push(flagRef || opts.codeAlways ? val : undefined); }
        val.argcount = rd(4).readInt32LE(0);
        val.posonly = rd(4).readInt32LE(0);
        val.kwonly = rd(4).readInt32LE(0);
        val.stacksize = rd(4).readInt32LE(0);
        val.flags = rd(4).readInt32LE(0);
        val.code = parse();
        val.consts = parse();
        val.names = parse();
        val.localsplusnames = parse();
        val.localspluskinds = parse();
        val.filename = parse();
        val.name = parse();
        val.qualname = parse();
        val.firstlineno = rd(4).readInt32LE(0);
        val.linetable = parse();
        val.exceptiontable = parse();
        if (!opts.codeBefore) { if (flagRef) refs.push(val); }
        return val;
      }
      default: throw new Error('type ' + JSON.stringify(c) + ' @' + pos);
    }
  }
  return { parse, pos: () => pos };
}

function validate(co, errs) {
  if (!co || !co.__code) return;
  for (const field of ['names', 'localsplusnames']) {
    const t = co[field];
    if (!Array.isArray(t)) { errs.push(`${co.name}: ${field} not tuple`); continue; }
    for (const e of t) if (typeof e !== 'string') { errs.push(`${co.name}: ${field} has non-string`); break; }
  }
  if (typeof co.filename !== 'string') errs.push(`${co.name}: bad filename`);
  if (typeof co.name !== 'string') errs.push(`${co.name}: bad name`);
  for (const c of co.consts || []) if (c && c.__code) validate(c, errs);
}

const data = readFileSync(process.argv[2]);
for (const containerBefore of [true, false])
  for (const codeBefore of [true, false])
    for (const reserveAlways of [true, false])
      for (const codeAlways of [true, false]) {
        const opts = { containerBefore, codeBefore, reserveAlways, codeAlways };
        try {
          const p = makeParser(data, opts);
          const co = p.parse();
          const errs = [];
          validate(co, errs);
          const tag = JSON.stringify(opts);
          if (errs.length === 0 && p.pos() === data.length) console.log('PERFECT', tag);
          else console.log('fail', tag, errs.slice(0, 2), 'pos', p.pos(), '/', data.length);
        } catch (e) {
          console.log('throw', JSON.stringify(opts), e.message);
        }
      }

